import{_ as d,o,c as t,a2 as c}from"./chunks/framework.DXa1R37q.js";const m=JSON.parse('{"title":"Design Docs tools","description":"","frontmatter":{},"headers":[],"relativePath":"design-docs/tools.md","filePath":"design-docs/tools.md","lastUpdated":1792947882000}'),r={name:"design-docs/tools.md"};function n(a,e,i,s,l,p){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="design-docs-tools" tabindex="-1">Design Docs tools <a class="header-anchor" href="#design-docs-tools" aria-label="Permalink to &quot;Design Docs tools&quot;">​</a></h1><p>All delivery methods use this registry order and reject unknown input fields.</p><table tabindex="0"><thead><tr><th>Tool</th><th>Exact input</th><th>Exact output</th></tr></thead><tbody><tr><td><code>document_id</code></td><td><code>{}</code></td><td><code>{id}</code></td></tr><tr><td><code>document_create</code></td><td><code>title</code> of 1-200 characters and <code>kind</code>; optional <code>created_by</code>, <code>body</code>, and <code>metadata</code></td><td>document record</td></tr><tr><td><code>document_list</code></td><td>optional <code>kind</code>, <code>status</code>, <code>location</code>, <code>id</code>, <code>current_only</code>, and <code>limit</code> of 1-1000</td><td><code>{documents: summary[]}</code></td></tr><tr><td><code>document_search</code></td><td>nonblank <code>query</code>; optional <code>kind</code>, <code>status</code>, <code>location</code>, <code>id</code>, <code>all_versions</code>, and <code>limit</code> of 1-1000</td><td><code>{hits: searchHit[]}</code></td></tr><tr><td><code>document_get</code></td><td><code>id</code>; optional positive <code>version</code></td><td>document record</td></tr><tr><td><code>document_update</code></td><td><code>id</code> and <code>expected_revision</code>; optional <code>title</code>, <code>kind</code>, <code>body</code>, and nullable <code>metadata</code></td><td>document record</td></tr><tr><td><code>document_transition</code></td><td><code>id</code>, <code>expected_revision</code>, <code>to</code>, nonblank <code>intent</code> up to 1000 characters, <code>actor</code> up to 200 characters, and <code>evidence</code></td><td>document record</td></tr><tr><td><code>document_version</code></td><td><code>id</code> and the latest approved <code>expected_revision</code>; optional <code>title</code>, <code>kind</code>, <code>body</code>, and nullable <code>metadata</code></td><td>successor document record</td></tr><tr><td><code>document_validate</code></td><td>optional <code>id</code> and <code>cross_domain</code></td><td>validation report</td></tr><tr><td><code>document_archive</code></td><td><code>id</code> and <code>expected_revision</code></td><td>operation report</td></tr><tr><td><code>document_restore</code></td><td><code>id</code> and <code>expected_revision</code></td><td>operation report</td></tr><tr><td><code>document_export</code></td><td><code>{}</code></td><td><code>{content}</code> deterministic bundle</td></tr><tr><td><code>document_import</code></td><td><code>content</code>; optional <code>preview</code>; optional <code>format</code>, which is <code>native</code> or <code>harnessctl-v2</code></td><td>import report</td></tr></tbody></table><p>A summary contains <code>id</code>, <code>path</code>, <code>revision</code>, <code>location</code>, <code>superseded</code>, <code>archived</code>, <code>title</code>, <code>kind</code>, <code>status</code>, and <code>version</code>. A document record adds <code>metadata</code> and <code>body</code>. A search hit adds <code>score</code> and <code>snippet</code>. A validation report contains <code>valid</code>, document and lineage counts, findings, and cache state. Archive and restore return <code>{id, location, documents}</code>. Import returns <code>preview</code>, <code>valid</code>, <code>additions</code>, <code>conflicts</code>, <code>unsupported</code>, <code>warnings</code>, and <code>path_mappings</code>.</p><p>Transition evidence requires <code>source: human-ui | caller-attestation | policy</code>; optional <code>reference</code> is at most 1000 characters and optional <code>note</code> is at most 4000. Import previews when <code>preview</code> is omitted. Updates, transitions, versioning, archive, and restore require <code>v1:&lt;sha256&gt;</code> revisions.</p><p>Every tool error contains <code>category</code>, <code>code</code>, <code>message</code>, <code>paths</code>, <code>retryable</code>, and optional bounded <code>details</code>. Input and output failures use <code>TOOL_INPUT_INVALID</code> and <code>TOOL_OUTPUT_INVALID</code>; oversized output uses <code>TOOL_RESULT_LIMIT</code>. Store errors preserve lifecycle, stale revision, link, path, contention, durability, recovery, cache, and resource-limit codes. Fetch current state before retrying a stale mutation.</p>',6)])])}const _=d(r,[["render",n]]);export{m as __pageData,_ as default};
